```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("temperatury.txt");
    vector<pair<string, int>> dane;
    string dzien;
    int temp;
    int suma = 0;
    while (plik >> dzien >> temp) {
        dane.push_back({dzien, temp});
        suma += temp;
    }
    double srednia = (double)suma / dane.size();

    cout << "a) Srednia temperatura: " << fixed << setprecision(2) << srednia << endl;

    int maxT = dane[0].second, minT = dane[0].second;
    string maxD = dane[0].first, minD = dane[0].first;
    for (auto &d : dane) {
        if (d.second > maxT) { maxT = d.second; maxD = d.first; }
        if (d.second < minT) { minT = d.second; minD = d.first; }
    }
    cout << endl << "b) Max: " << maxD << " (" << maxT << ")" << endl;
    cout << "   Min: " << minD << " (" << minT << ")" << endl;

    int cnt = 0;
    for (auto &d : dane) {
        if (d.second > srednia) cnt++;
    }
    cout << endl << "c) Dni powyzej sredniej: " << cnt << endl;
    return 0;
}
```

Weryfikacja:
- Suma: 12+15+8+20+18+14+11 = 98
- Srednia: 98/7 = 14.00
- Max: Cz(20), Min: Sr(8)
- Dni > 14.00: Wt(15), Cz(20), Pt(18) -> 3
